def split_colors_into_sizes(apps, schema_editor):
	"""A color-fan product that also has size prices becomes one row per size.

	The color's own unit price is copied onto every size. The existing barcode
	stays on the first size by display order; the other sizes start empty.
	The original row without a size is removed, so a quantity typed on it
	does not move onto a size.
	"""
	Subcategory = apps.get_model("white_catalog", "WhiteSubcategory")
	Price = apps.get_model("white_catalog", "WhiteSubcategoryPrice")
	SizeType = apps.get_model("white_catalog", "WhiteSizeType")
	ColorVariant = apps.get_model("white_catalog", "WhiteColorVariant")

	product_ids = (
		Subcategory.objects.filter(has_color_variants=True, size_prices__isnull=False)
		.distinct()
		.values_list("pk", flat=True)
	)
	for product_id in product_ids:
		prices = list(Price.objects.filter(subcategory_id=product_id).order_by("order", "id"))
		sizes = []
		seen_names = set()
		for price in prices:
			name = (price.size_name or "").strip()
			if not name or name in seen_names:
				continue
			seen_names.add(name)
			size, _created = SizeType.objects.get_or_create(
				name=name,
				defaults={"order": price.order or 0, "is_active": True},
			)
			sizes.append((size, price.order or 0))
		if not sizes:
			continue
		unsized = list(ColorVariant.objects.filter(product_id=product_id, size__isnull=True))
		for variant in unsized:
			barcode = (variant.barcode or "").strip() or None
			if barcode:
				variant.barcode = None
				variant.save(update_fields=["barcode"])
			image_name = variant.image.name if variant.image else ""
			for index, (size, size_order) in enumerate(sizes):
				if ColorVariant.objects.filter(
					product_id=product_id,
					color_id=variant.color_id,
					size_id=size.pk,
				).exists():
					continue
				created = ColorVariant(
					product_id=product_id,
					color_id=variant.color_id,
					size_id=size.pk,
					barcode=barcode if index == 0 else None,
					unit_price=variant.unit_price,
					is_active=variant.is_active,
					order=size_order,
				)
				if image_name:
					created.image = image_name
				created.save()
			variant.delete()


